import {
  HELP_FLAGS,
  PARSE_ERROR_EXIT_CODE,
  REQUIRED_OPTION,
} from './constants.mjs';
import {
  formatExpectedArgumentError,
  formatHelp,
  formatRequiredError,
  formatUnrecognizedArgumentsError,
} from './format.mjs';
import { looksLikeNegativeNumber } from './negative-number.mjs';

function isHelpFlag(token) {
  return HELP_FLAGS.includes(token);
}

function isAttachedRequiredOption(token) {
  return token.length >= 4 && token.slice(0, 4) === '--a=';
}

function createHelpResult(programName) {
  return {
    exitCode: 0,
    kind: 'help',
    text: formatHelp(programName),
  };
}

function createErrorResult(programName, text) {
  return {
    exitCode: PARSE_ERROR_EXIT_CODE,
    kind: 'error',
    text,
  };
}

export function parseCommandLine(argv, programName) {
  let value;
  let expectsValue = false;
  const unknownArguments = [];

  for (const token of argv) {
    if (expectsValue) {
      if (token.startsWith('-') && !looksLikeNegativeNumber(token)) {
        return createErrorResult(programName, formatExpectedArgumentError(programName));
      }

      value = token;
      expectsValue = false;
      continue;
    }

    if (isHelpFlag(token)) {
      return createHelpResult(programName);
    }

    if (token === REQUIRED_OPTION) {
      expectsValue = true;
      continue;
    }

    if (isAttachedRequiredOption(token)) {
      value = token.slice(4);
      continue;
    }

    unknownArguments.push(token);
  }

  if (expectsValue) {
    return createErrorResult(programName, formatExpectedArgumentError(programName));
  }

  if (typeof value === 'undefined') {
    return createErrorResult(programName, formatRequiredError(programName));
  }

  if (unknownArguments.length > 0) {
    return createErrorResult(
      programName,
      formatUnrecognizedArgumentsError(programName, unknownArguments),
    );
  }

  return {
    kind: 'ok',
    value,
  };
}

